package br.com.tapeteskalke.controller; import br.com.tapeteskalke.dto.*; import br.com.tapeteskalke.dto.ProdutoDtos.AjusteRequest; import br.com.tapeteskalke.repository.*; import br.com.tapeteskalke.service.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.web.bind.annotation.*; import org.springframework.transaction.annotation.Transactional;
@RestController @RequestMapping("/api/v1/estoque") public class EstoqueController { private final ProdutoRepository produtos; private final MovimentoEstoqueRepository movimentos; private final ProdutoService productService; private final EstoqueService estoque; private final PermissionService permissions; public EstoqueController(ProdutoRepository produtos,MovimentoEstoqueRepository movimentos,ProdutoService productService,EstoqueService estoque,PermissionService permissions){this.produtos=produtos;this.movimentos=movimentos;this.productService=productService;this.estoque=estoque;this.permissions=permissions;} @GetMapping public ApiResponse<?> list(){permissions.page("produtos");return ApiResponse.ok(productService.list("",0,100));} @GetMapping("/resumo") public ApiResponse<?> resumo(){permissions.page("produtos");var low=produtos.lowStock();return ApiResponse.ok(Map.of("baixoOuEsgotado",low.size(),"produtos",low.stream().map(productService::response).toList()));} @GetMapping("/baixo") public ApiResponse<?> baixo(){permissions.page("produtos");return ApiResponse.ok(produtos.lowStock().stream().map(productService::response).toList());} @GetMapping("/movimentos") public ApiResponse<?> movimentos(){permissions.page("produtos");return ApiResponse.ok(movimentos.recent(org.springframework.data.domain.PageRequest.of(0,200)).stream().map(m->Map.of("id",m.getId(),"produto",m.getProduto().getNome(),"saldo",m.getSaldo(),"tipo",m.getTipoMovimento(),"quantidade",m.getQuantidade(),"data",m.getDataMovimento())).toList());} @PostMapping("/ajuste") @Transactional public ApiResponse<?> ajustar(@Valid @RequestBody AjusteRequest r){permissions.action("estoque_ajustar");if(r.quantidade().signum()==0)throw new br.com.tapeteskalke.exception.BusinessException("QUANTIDADE_INVALIDA","A quantidade do ajuste não pode ser zero",org.springframework.http.HttpStatus.UNPROCESSABLE_ENTITY);var p=productService.locked(r.produtoId());estoque.change(p,r.saldo(),r.quantidade(),"AJUSTE_MANUAL","AJUSTE",java.util.UUID.randomUUID().toString(),r.observacao());return ApiResponse.ok(productService.response(p));} }